**What this code covers**

- Comprehensive evaluation suite for GraphRAG systems.
- P@K = |retrieved ∩ relevant| / k
- R@K = |retrieved ∩ relevant| / |relevant|
- MRR = 1/rank of first relevant result

**Defines:** `EvalSample`, `GraphRAGEvaluator`

```python
# evaluation/graphrag_evaluator.py

import json
import numpy as np
from dataclasses import dataclass
from typing import List, Dict, Tuple
from openai import OpenAI

@dataclass
class EvalSample:
    query: str
    expected_answer: str
    relevant_doc_ids: List[str]
    query_type: str  # "local", "global", "relational"

class GraphRAGEvaluator:
    """
    Comprehensive evaluation suite for GraphRAG systems.

    Metrics:
    - Retrieval: NDCG@K, MRR, Recall@K, Precision@K
    - Generation: Faithfulness, Relevance, Completeness
    - Latency: P50, P95, P99
    - Cost: Tokens per query
    """

    def __init__(self, system, eval_dataset: List[EvalSample]):
        self.system = system
        self.dataset = eval_dataset
        self.client = OpenAI()
        self.results = []

    # ── RETRIEVAL METRICS ──────────────────────────────────────────────

    def precision_at_k(self, retrieved: List[str], 
                        relevant: List[str], k: int) -> float:
        """P@K = |retrieved ∩ relevant| / k"""
        retrieved_k = set(retrieved[:k])
        return len(retrieved_k & set(relevant)) / k

    def recall_at_k(self, retrieved: List[str],
                     relevant: List[str], k: int) -> float:
        """R@K = |retrieved ∩ relevant| / |relevant|"""
        if not relevant:
            return 0.0
        retrieved_k = set(retrieved[:k])
        return len(retrieved_k & set(relevant)) / len(relevant)

    def mrr(self, retrieved: List[str], relevant: List[str]) -> float:
        """MRR = 1/rank of first relevant result"""
        relevant_set = set(relevant)
        for rank, doc_id in enumerate(retrieved, 1):
            if doc_id in relevant_set:
                return 1.0 / rank
        return 0.0

    def ndcg_at_k(self, retrieved: List[str],
                   relevant: List[str], k: int) -> float:
        """NDCG@K with binary relevance"""
        dcg = sum(
            1.0 / np.log2(rank + 2)
            for rank, doc_id in enumerate(retrieved[:k])
            if doc_id in set(relevant)
        )
        ideal_hits = min(len(relevant), k)
        idcg = sum(1.0 / np.log2(i + 2) for i in range(ideal_hits))
        return dcg / idcg if idcg > 0 else 0.0

    # ── GENERATION METRICS (LLM-as-Judge) ─────────────────────────────

    def evaluate_faithfulness(self, answer: str, context: str) -> float:
        """
        Faithfulness: Is the answer grounded in the retrieved context?
        Score 0-1 (LLM judge)
        """
        response = self.client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{
                "role": "user",
                "content": f"""
                Rate the faithfulness of the answer to the given context on a scale of 0-10.

                Context: {context[:2000]}

                Answer: {answer}

                Faithfulness criteria:
                - 10: All claims directly supported by context
                - 5: Some claims supported, some are inferences
                - 0: Answer contradicts or ignores context

                Return ONLY a number 0-10.
                """
            }],
            max_tokens=5,
            temperature=0
        )

        try:
            score = float(response.choices[0].message.content.strip())
            return score / 10.0
        except ValueError:
            return 0.5

    def evaluate_answer_relevance(self, query: str, answer: str) -> float:
        """Does the answer actually address the question?"""
        response = self.client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{
                "role": "user",
                "content": f"""
                Rate how well the answer addresses the question (0-10).

                Question: {query}
                Answer: {answer}

                Return ONLY a number 0-10.
                """
            }],
            max_tokens=5,
            temperature=0
        )

        try:
            return float(response.choices[0].message.content.strip()) / 10.0
        except ValueError:
            return 0.5

    def evaluate_completeness(self, query: str, answer: str, 
                               expected: str) -> float:
        """Does the answer cover all aspects of the expected answer?"""
        response = self.client.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{
                "role": "user",
                "content": f"""
                Compare the generated answer against the expected answer for completeness (0-10).

                Question: {query}
                Expected: {expected}
                Generated: {answer}

                Return ONLY a number 0-10.
                """
            }],
            max_tokens=5,
            temperature=0
        )

        try:
            return float(response.choices[0].message.content.strip()) / 10.0
        except ValueError:
            return 0.5

    # ── FULL EVALUATION RUN ────────────────────────────────────────────

    def run_full_evaluation(self, k_values: List[int] = [1, 3, 5, 10]) -> dict:
        """Run complete evaluation across all metrics"""
        import time

        all_metrics = {
            "retrieval": {f"ndcg@{k}": [] for k in k_values},
            "retrieval_mrr": [],
            "generation": {
                "faithfulness": [],
                "relevance": [],
                "completeness": []
            },
            "latency_ms": [],
            "by_query_type": {}
        }

        for i, sample in enumerate(self.dataset):
            print(f"Evaluating sample {i+1}/{len(self.dataset)}: {sample.query[:50]}...")

            t_start = time.time()
            result = self.system.query(sample.query)
            latency = (time.time() - t_start) * 1000

            all_metrics["latency_ms"].append(latency)

            # Retrieval metrics
            retrieved_ids = result.get("sources", [])
            for k in k_values:
                ndcg = self.ndcg_at_k(retrieved_ids, sample.relevant_doc_ids, k)
                all_metrics["retrieval"][f"ndcg@{k}"].append(ndcg)

            all_metrics["retrieval_mrr"].append(
                self.mrr(retrieved_ids, sample.relevant_doc_ids)
            )

            # Generation metrics
            answer = result.get("answer", "")
            context = result.get("context", "")

            all_metrics["generation"]["faithfulness"].append(
                self.evaluate_faithfulness(answer, context)
            )
            all_metrics["generation"]["relevance"].append(
                self.evaluate_answer_relevance(sample.query, answer)
            )
            all_metrics["generation"]["completeness"].append(
                self.evaluate_completeness(sample.query, answer, sample.expected_answer)
            )

        # Compute final metrics
        return self._aggregate_metrics(all_metrics, k_values)

    def _aggregate_metrics(self, all_metrics: dict, k_values: list) -> dict:
        """Aggregate and format final metrics"""
        latencies = sorted(all_metrics["latency_ms"])
        n = len(latencies)

        report = {
            "RETRIEVAL METRICS": {
                f"NDCG@{k}": f"{np.mean(all_metrics['retrieval'][f'ndcg@{k}']):.4f}"
                for k in k_values
            },
            "MRR": f"{np.mean(all_metrics['retrieval_mrr']):.4f}",

            "GENERATION METRICS": {
                "Faithfulness":  f"{np.mean(all_metrics['generation']['faithfulness']):.4f}",
                "Relevance":     f"{np.mean(all_metrics['generation']['relevance']):.4f}",
                "Completeness":  f"{np.mean(all_metrics['generation']['completeness']):.4f}",
            },

            "LATENCY": {
                "P50":  f"{latencies[n//2]:.1f}ms",
                "P95":  f"{latencies[int(n*0.95)]:.1f}ms",
                "P99":  f"{latencies[int(n*0.99)]:.1f}ms",
                "Mean": f"{np.mean(latencies):.1f}ms"
            }
        }

        self._print_report(report)
        return report

    def _print_report(self, report: dict):
        """Pretty print evaluation report"""
        print("\n" + "="*60)
        print("📊 GRAPHRAG EVALUATION REPORT")
        print("="*60)

        for section, metrics in report.items():
            print(f"\n{section}:")
            if isinstance(metrics, dict):
                for metric, value in metrics.items():
                    print(f"  {metric:<20} {value}")
            else:
                print(f"  {metrics}")
        print("="*60)
```
